import { seedState } from './seed.js';
import { baseUnit, unitCost, ingredientCost, calculateRecipe, priceFor, analyzePrice } from './pricing.js';
import { icon } from './icons.js';
import { validateState } from './state.js';
import { parseNumber, roundCurrency } from './numbers.js';

const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => typeof n==='number'&&Number.isFinite(n)?n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'—';
const dec = (n,p=2) => Number(n).toLocaleString('pt-BR',{maximumFractionDigits:p});
const pct = n => n==null?'—':dec(n,1)+'%';
const num = parseNumber;
const val = n => String(n??'').replace('.',',');
const id = () => crypto.randomUUID();
const stamp = () => new Date().toISOString();
const date = s => s?new Date(s.length===10?s+'T12:00:00':s).toLocaleDateString('pt-BR'):'Hoje';
const labelUnit = u => ({un:'unidade',kg:'kg',g:'g',ml:'ml',L:'L'}[u]||u);
const STORAGE='kalyne.precificacao.v1';
let loadWarning='';
let state;
let recoveryRaw=null, persistenceBlocked=false, remoteChanged=false;
try { recoveryRaw=localStorage.getItem(STORAGE); state=validateState(recoveryRaw?JSON.parse(recoveryRaw):seedState()); recoveryRaw=null; }
catch { state=validateState(seedState());persistenceBlocked=true;loadWarning='Os dados salvos precisam de recuperação. Eles foram preservados. Use Fazer backup para baixar o arquivo original e restaure um backup válido em Mais.'; }
let current={page:'home',id:null};
let draft=null, ingredientTab='ingredient', ingredientSearch='', recipeSearch='', selectedScenario='pix';
let sim=null, toastTimer, previousFocus, draftBaseline=null, costsBaseline=null, pendingLeave=null, priceRecipeId=null;
const recipeBy = rid => state.recipes.find(r=>r.id===rid);
const activeRecipes=()=>state.recipes.filter(r=>!r.archived);
const cost = r => calculateRecipe(r,state.ingredients,state.recipes,state.settings);
function updateState(change,{replace=false}={}) {
  if(persistenceBlocked&&!replace)throw Error('Seus dados originais foram preservados. Baixe o arquivo de recuperação e restaure um backup válido antes de salvar.');
  if(remoteChanged&&!replace)throw Error('Outra aba alterou este caderno. Guarde suas alterações e reabra os dados antes de salvar.');
  const next=structuredClone(state);change(next);
  try {
    const raw=localStorage.getItem(STORAGE);
    let revision=0;
    try{revision=raw?validateState(JSON.parse(raw)).revision:0;}catch(error){if(!replace)throw error;}
    if(!replace&&revision!==state.revision)throw Error('Outra aba alterou o caderno. Recarregue para usar os dados atuais.');
    next.revision=Math.max(revision,state.revision)+1;
    const checked=validateState(next);
    localStorage.setItem(STORAGE,JSON.stringify(checked));state=checked;
  }catch(error){throw new Error(error.name==='QuotaExceededError'?'O navegador ficou sem espaço. Exporte um backup antes de continuar.':error.message||'Não foi possível salvar os dados neste navegador.');}
  if(replace){persistenceBlocked=false;recoveryRaw=null;remoteChanged=false;loadWarning='';}
}
function notify(message){ const el=$('#toast-root');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4200); }
function route(page,rid){ location.hash='/'+page+(rid?'/'+encodeURIComponent(rid):''); }
function button(text,action,cls='primary',extra=''){return `<button type="button" class="button ${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function field(label,name,value,extra='',type='text'){return `<div class="field"><label for="${esc(name)}">${label}</label><input id="${esc(name)}" name="${esc(name)}" type="${type}" value="${esc(typeof value==='number'&&type!=='number'?val(value):value)}" ${extra}></div>`;}
function select(label,name,value,options,extra=''){return `<div class="field"><label for="${esc(name)}">${label}</label><select id="${esc(name)}" name="${esc(name)}" ${extra}>${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;}
function notice(text,type='info'){return `<div class="notice ${type}">${icon(type==='warning'?'alert':'info',18)}<span>${text}</span></div>`;}
function heading(title,sub='',actions=''){return `<div class="page-heading"><div><h1>${title}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div><div class="page-actions">${actions}</div></div>`;}
function empty(title,text,action=''){return `<div class="empty-state">${icon('book',36)}<h3>${title}</h3><p>${text}</p>${action}</div>`;}
function thumb(r){return `<div class="product-thumb"><img src="./assets/${r.image==='brownie'?'brownie':'brigadeiro'}.png" alt="" loading="lazy"></div>`;}
function safeCost(r){try{return {c:cost(r)};}catch(e){return {error:e.message};}}
function safePricing(r){const x=safeCost(r);if(x.error)return x;const scenario=state.scenarios.find(sc=>sc.id===r.priceScenario)||state.scenarios[0];try{return {...x,scenario,p:priceFor(x.c.unitCost,scenario.margin??r.margin??40,scenario.fee,state.settings.taxRate)};}catch(e){return {...x,scenario,error:e.message};}}
const nav=[['home','Início','home'],['ingredients','Insumos','jar'],['recipes','Receitas','chef'],['costs','Custos de produção','costs'],['simulator','Simulador','calculator'],['sheets','Minhas fichas','receipt']];
function navLink(page,label,ic,mobile=false){const active=current.page===page||page==='recipes'&&['edit','price'].includes(current.page);return `<a href="#/${page}" class="nav-item ${active?'active':''}" ${active?'aria-current="page"':''}>${icon(ic,22)}<span>${label}</span>${!mobile?icon('chevron',15):''}</a>`;}
function shell(content){
  const name=nav.find(x=>x[0]===current.page)?.[1]||({edit:'Ficha técnica',price:'Preço sugerido',more:'Mais opções'}[current.page]||'Kalyne');
  $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand-link" href="#/home" aria-label="Kalyne Chocolateria, início"><img class="brand-logo" src="./assets/logo.png" alt="Kalyne Chocolateria"></a><div class="nav-label">SEU CADERNO DE PREÇOS</div><nav class="desktop-nav" aria-label="Navegação principal">${nav.map(x=>navLink(...x)).join('')}</nav><div class="sidebar-bottom">${button(icon('download',18)+' Fazer backup','backup','secondary small')}<p>${icon('check',14)} Salvo neste navegador</p><a href="#/more">Preferências e dados ${icon('arrow',14)}</a></div></aside><main class="main-area"><header class="mobile-brand"><a href="#/home"><img class="brand-logo" src="./assets/logo.png" alt="Kalyne Chocolateria"></a></header><header class="topbar"><div class="breadcrumb">Seu ateliê ${icon('chevron',13)} <strong>${name}</strong></div><div class="topbar-actions">${state.example?'<span class="badge">Dados de exemplo</span>':''}<a href="#/more" class="icon-button" aria-label="Preferências e dados">${icon('settings',21)}</a></div></header><div class="content">${loadWarning?notice(esc(loadWarning),'warning'):''}${content}<footer class="content-footer">Feito com cuidado para a Kalyne <span>♥</span></footer></div></main><nav class="bottom-nav" aria-label="Navegação principal">${navLink('home','Início','home',true)}${navLink('ingredients','Insumos','jar',true)}${navLink('recipes','Receitas','chef',true)}${navLink('more','Mais','more',true)}</nav></div>`;
}
function recipeRow(r){const x=safePricing(r);return `<div class="list-row">${thumb(r)}<a class="row-main" href="#/price/${esc(r.id)}"><strong class="row-title">${esc(r.name)}</strong><span class="row-sub">${dec(r.yield)} ${esc(r.yieldUnit)} · ${esc(r.category||'Receita')}</span></a><div class="row-value">${x.error?'<span class="badge warning">Revisar ficha</span>':`<strong>${money(x.p.price)} <small>/ ${esc(r.yieldUnit)}</small></strong><span class="row-sub">${esc(x.scenario.name)} · ${pct(x.p.margin)}</span>`}</div><a class="icon-button" href="#/price/${esc(r.id)}" aria-label="Abrir ${esc(r.name)}">${icon('chevron',19)}</a></div>`;}
function homePage(){const recipes=activeRecipes(); const focus=recipes[0];const x=focus?safePricing(focus):{};let summary='';if(x.c)summary=breakdown(x.c);
  return `${state.example?notice('Você está vendo exemplos editáveis. Cadastre os seus valores ou <a href="#/more">comece com o caderno vazio</a>.'):''}<section class="hero"><div class="hero-content"><span class="eyebrow">CADA INGREDIENTE NA CONTA</span><h1>Vamos<br>precificar?<span class="hero-heart">♡</span></h1><p>Calcule o custo das suas receitas<br>e venda com mais segurança.</p>${button(icon('plus',23)+' Nova precificação '+icon('arrow',19),'new-recipe')}</div><div class="hero-art"><img src="./assets/brigadeiro.png" alt="Brigadeiro de chocolate em forminha rosa"><span class="hero-art-tag">Seu talento merece<br><strong>o preço certo.</strong></span></div></section><div class="stats-grid"><a class="stat-card" href="#/recipes"><div class="stat-icon">${icon('book',28)}</div><div><strong class="stat-number">${recipes.length}</strong><span class="stat-label">receitas no caderno</span></div>${icon('chevron',19)}</a><a class="stat-card" href="#/ingredients"><div class="stat-icon">${icon('jar',28)}</div><div><strong class="stat-number">${state.ingredients.filter(i=>!i.archived).length}</strong><span class="stat-label">insumos cadastrados</span></div>${icon('chevron',19)}</a><a class="stat-card" href="#/sheets"><div class="stat-icon">${icon('receipt',28)}</div><div><strong class="stat-number">${state.sheets.length}</strong><span class="stat-label">fichas de preço salvas</span></div>${icon('chevron',19)}</a></div><div class="grid two"><section class="panel"><div class="panel-heading"><h2>Suas receitas</h2><a href="#/recipes">Ver todas ${icon('arrow',15)}</a></div><div class="list">${recipes.length?recipes.slice(0,4).map(recipeRow).join(''):empty('Seu caderno começa aqui','Cadastre seus ingredientes e monte a primeira receita.',button('Criar receita','new-recipe'))}</div></section><section class="panel"><div class="panel-heading"><h2>De onde vem o custo</h2>${icon('heart',22)}</div><div class="panel-body">${focus&&x.c?`<p class="subtitle">${esc(focus.name)} · lote de ${dec(focus.yield)} ${esc(focus.yieldUnit)}</p>${summary}<div class="summary-row total"><span>Custo por ${labelUnit(focus.yieldUnit)}</span><strong>${money(x.c.unitCost)}</strong></div><a href="#/price/${esc(focus.id)}" class="button secondary">Ver cálculo completo ${icon('arrow',18)}</a>`:empty('Tudo às claras','O custo de cada etapa aparece aqui.')}</div></section></div>`;
}
function ingredientsPage(){return `${heading('Insumos','Cadastre o valor que você paga.',button(icon('plus',20)+' Novo insumo','new-ingredient'))}<div class="toolbar"><div class="search-field">${icon('search',20)}<input id="ingredient-search" type="search" placeholder="Buscar ingrediente ou embalagem" aria-label="Buscar ingrediente ou embalagem" value="${esc(ingredientSearch)}"></div><div class="filter-tabs" aria-label="Categoria de insumos">${[['ingredient','Ingredientes'],['packaging','Embalagens'],['archived','Arquivados']].map(([v,t])=>`<button type="button" data-action="ingredient-tab" data-value="${v}" class="${ingredientTab===v?'active':''}" aria-pressed="${ingredientTab===v}">${t}</button>`).join('')}</div></div><section class="panel"><div class="list" id="ingredient-results">${ingredientResults()}</div></section>${notice('O preço da compra vira custo da quantidade usada. Exemplo: 1 kg por R$ 30 + 200 g usados = R$ 6 na receita.')}`;}
function ingredientResults(){const list=state.ingredients.filter(i=>(ingredientTab==='archived'?i.archived:!i.archived&&i.category===ingredientTab)&&i.name.toLocaleLowerCase('pt-BR').includes(ingredientSearch.toLocaleLowerCase('pt-BR')));return list.length?list.map(i=>`<div class="list-row"><div class="ingredient-emoji" aria-hidden="true">${esc(i.emoji|| (i.category==='packaging'?'🧁':'🍫'))}</div><div class="row-main"><strong class="row-title">${esc(i.name)}</strong><span class="row-sub">${money(i.price)} · ${dec(i.quantity,3)} ${esc(i.unit)}${i.brand?' · '+esc(i.brand):''}</span><span class="row-sub">Atualizado em ${date(i.updatedAt)}</span></div><div class="row-value"><strong>${money(unitCost(i)* (baseUnit(i.unit)==='un'?1:100))}</strong><span class="row-sub">por ${baseUnit(i.unit)==='un'?'unidade':'100 '+esc(baseUnit(i.unit))}</span></div><div class="row-actions">${button(icon(i.archived?'refresh':'edit',19),i.archived?'restore-ingredient':'edit-ingredient','icon-button',`data-id="${esc(i.id)}" aria-label="${i.archived?'Restaurar':'Editar'} ${esc(i.name)}"`)}</div></div>`).join(''):empty('Nenhum insumo por aqui','Adicione o que você usa nas suas receitas.',button(icon('plus',18)+' Cadastrar insumo','new-ingredient'));}
function recipesPage(){return `${heading('Suas receitas','O seu caderno de receitas, com cada custo no lugar.',button(icon('plus',20)+' Nova receita','new-recipe'))}<div class="toolbar"><div class="search-field">${icon('search',20)}<input id="recipe-search" type="search" placeholder="Buscar receita" aria-label="Buscar receita" value="${esc(recipeSearch)}"></div></div><section class="panel"><div class="list" id="recipe-results">${recipeResults()}</div></section>`;}
function recipeResults(){const list=activeRecipes().filter(r=>r.name.toLocaleLowerCase('pt-BR').includes(recipeSearch.toLocaleLowerCase('pt-BR')));return list.length?list.map(recipeRow).join(''):empty('Vamos criar uma receita?','Escolha os ingredientes, informe as quantidades e o rendimento.',button('Criar receita','new-recipe'));}
function makeDraft(rid){draft=rid?structuredClone(recipeBy(rid)):{id:id(),name:'',category:'Docinhos',yield:50,yieldUnit:'un',weightGrams:undefined,minutes:0,productionMinutes:0,directCost:state.settings.defaultDirectCost??2,margin:40,price:0,image:'brigadeiro',notes:'',items:[],packaging:[]};draftBaseline=JSON.stringify(draft);}
function optionsForItem(){return [...state.ingredients.filter(i=>!i.archived&&i.category==='ingredient').map(i=>['ingredient:'+i.id,i.name]),...activeRecipes().filter(r=>r.id!==draft.id).map(r=>['recipe:'+r.id,'Receita base · '+r.name])];}
function recipeEditor(){if(!draft||current.id&&draft.id!==current.id)makeDraft(current.id);if(!draft)return empty('Receita não encontrada','Abra uma receita no seu caderno.');return `${heading('Ficha técnica','Conte o que vai na receita. A gente faz as contas.',`<a href="#/recipes" class="button ghost">${icon('arrowLeft',18)} Voltar</a>`)}<form id="recipe-form" novalidate><div class="grid two editor-grid"><div class="editor-main"><section class="panel"><div class="panel-heading"><h2>Sobre a receita</h2>${icon('chef',22)}</div><div class="panel-body"><div class="form-grid">${field('Nome da receita','recipe-name',draft.name,'required maxlength="100" placeholder="Ex.: Brigadeiro clássico"')}${select('Categoria','recipe-category',draft.category,['Docinhos','Brownies','Bolos','Sobremesas','Receita base','Outros'].map(v=>[v,v]))}</div></div></section><section class="panel"><div class="panel-heading"><h2>Ingredientes do lote</h2>${button(icon('plus',18)+' Adicionar','add-recipe-line','secondary small')}</div><div class="panel-body recipe-lines" id="recipe-lines">${editorLines('items')}</div><div class="panel-body summary-row total"><span>Subtotal dos ingredientes</span><strong id="draft-ingredient-total">—</strong></div></section><section class="panel"><div class="panel-heading"><h2>Embalagens do lote</h2>${button(icon('plus',18)+' Adicionar','add-packaging-line','secondary small')}</div><div class="panel-body recipe-lines" id="packaging-lines">${editorLines('packaging')}</div></section><section class="panel"><div class="panel-heading"><h2>Observações</h2></div><div class="panel-body"><div class="field"><label for="recipe-notes">Seu jeito de fazer (opcional)</label><textarea id="recipe-notes" rows="3" maxlength="2000" placeholder="Detalhes da receita, peso dos doces, acabamento…">${esc(draft.notes)}</textarea></div></div></section></div><div class="editor-aside"><section class="panel"><div class="panel-heading"><h2>Rendimento e tempo</h2>${icon('clock',21)}</div><div class="panel-body"><div class="form-grid">${field('Rendimento vendável','recipe-yield',draft.yield,'inputmode="decimal" required')}${select('Unidade de venda','recipe-unit',draft.yieldUnit,[['un','Unidades'],['kg','Quilogramas (kg)'],['g','Gramas (base)']])}</div><p class="field-help">Informe o que fica pronto para vender, já descontando as perdas. Use vírgula para decimais: 0,125 kg.</p><div class="form-grid">${field('Trabalho ativo (min)','recipe-minutes',draft.minutes,'inputmode="decimal"')}${field('Tempo produtivo (min)','recipe-production',draft.productionMinutes,'inputmode="decimal"')}</div><p class="field-help">Trabalho ativo remunera seu tempo. Tempo produtivo distribui os custos fixos.</p>${field('Peso final do lote (g) · opcional','recipe-weight',draft.weightGrams||'','inputmode="decimal" placeholder="Para comparar o preço por kg"')}</div></section><section class="panel"><div class="panel-heading"><h2>Produção</h2>${icon('costs',21)}</div><div class="panel-body">${field('Gás, energia e outros diretos / lote (R$)','recipe-direct',draft.directCost,'inputmode="decimal"')}<p class="field-help">Use somente despesas que não estejam nos custos fixos.</p><a href="#/costs" class="text-link">Configurar minha hora e custos fixos ${icon('arrow',15)}</a></div></section><section class="panel"><div class="panel-body"><div class="summary-row total"><span>Custo do lote</span><strong id="draft-total">—</strong></div><div class="summary-row"><span>Custo por unidade de venda</span><strong id="draft-unit-total">—</strong></div><p id="draft-error" class="field-error" role="alert"></p><button type="submit" class="button primary full">${icon('calculator',20)} Calcular preço</button>${button(icon('scale',18)+' Ajustar quantidade do lote','scale-recipe','ghost full')}</div></section></div></div></form>`;}
function editorLines(key){const arr=draft[key];if(!arr.length)return `<p class="field-help">${key==='items'?'Adicione os ingredientes e as quantidades usadas.':'Adicione as forminhas, potes ou caixas usados neste lote.'}</p>`;return arr.map((line,index)=>{const target=line.type==='recipe'?recipeBy(line.id):state.ingredients.find(i=>i.id===line.id);const options=key==='items'?optionsForItem():state.ingredients.filter(i=>!i.archived&&i.category==='packaging').map(i=>[i.id,i.name]);const choice=key==='items'?(line.type||'ingredient')+':'+line.id:line.id;if(target&&!options.some(x=>x[0]===choice))options.push([choice,target.name+' (arquivado)']);let lineCost=0;try{lineCost=key==='items'&&line.type==='recipe'?cost({...draft,items:[line],packaging:[]}).ingredientCost:ingredientCost(target,line.quantity,line.unit);}catch{}return `<div class="recipe-line" data-key="${key}" data-index="${index}"><div class="line-name"><label class="sr-only" for="${key}-${index}-item">${key==='items'?'Ingrediente':'Embalagem'}</label><select id="${key}-${index}-item" data-line-field="id">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===choice?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="quantity-control"><label class="sr-only" for="${key}-${index}-qty">Quantidade usada</label><input id="${key}-${index}-qty" data-line-field="quantity" inputmode="decimal" value="${val(line.quantity)}" aria-label="Quantidade usada de ${esc(target?.name||'item')}"><label class="sr-only" for="${key}-${index}-unit">Unidade</label><select id="${key}-${index}-unit" data-line-field="unit">${['g','kg','ml','L','un'].map(u=>`<option ${u===line.unit?'selected':''}>${u}</option>`).join('')}</select></div><strong class="line-cost">${money(lineCost)}</strong>${button(icon('close',17),'remove-line','icon-button',`data-key="${key}" data-index="${index}" aria-label="Remover item"`)}</div>`;}).join('');}
function pullDraft(){if(!draft||!$('#recipe-form'))return;draft.name=$('#recipe-name').value.trim();draft.category=$('#recipe-category').value;draft.yield=num($('#recipe-yield').value);draft.yieldUnit=$('#recipe-unit').value;draft.minutes=num($('#recipe-minutes').value);draft.productionMinutes=num($('#recipe-production').value);draft.weightGrams=draft.yieldUnit==='kg'?draft.yield*1000:draft.yieldUnit==='g'?draft.yield:$('#recipe-weight').value.trim()===''?undefined:num($('#recipe-weight').value);const massYield=draft.yieldUnit!=='un';$('#recipe-weight').readOnly=massYield;if(massYield)$('#recipe-weight').value=val(draft.weightGrams);draft.directCost=num($('#recipe-direct').value);draft.notes=$('#recipe-notes').value.trim();$$('.recipe-line').forEach(el=>{const line=draft[el.dataset.key][Number(el.dataset.index)];const choice=$('[data-line-field="id"]',el).value;if(el.dataset.key==='items'){const [type,rid]=choice.split(':');line.type=type;line.id=rid;}else line.id=choice;line.quantity=num($('[data-line-field="quantity"]',el).value);line.unit=$('[data-line-field="unit"]',el).value;});}
function updateDraftTotals(){const usesBase=draft.items.some(line=>line.type==='recipe');if(usesBase&&!$('#base-recipe-note'))$('#recipe-lines').insertAdjacentHTML('beforeend',`<div id="base-recipe-note">${notice('Receitas base transferem somente os ingredientes. Inclua o tempo de preparo da base no tempo total deste produto.')}</div>`);if(!usesBase)$('#base-recipe-note')?.remove();try{const c=cost(draft);$('#draft-ingredient-total').textContent=money(c.ingredientCost);$('#draft-total').textContent=money(c.totalCost);$('#draft-unit-total').textContent=money(c.unitCost);$('#draft-error').textContent='';$$('.recipe-line').forEach(el=>{const key=el.dataset.key;const line=(key==='items'?c.ingredientLines:c.packagingLines)[Number(el.dataset.index)];$('.line-cost',el).textContent=money(line?.cost||0);});}catch(e){$('#draft-error').textContent=e.message;$('#draft-total').textContent='—';$('#draft-unit-total').textContent='—';}}
function breakdown(c){const rows=[['Ingredientes',c.ingredientCost,'#df5879'],['Embalagens',c.packagingCost,'#ec9a99'],['Seu trabalho',c.laborCost,'#a93652'],['Custos fixos',c.fixedCost,'#b98c7a'],['Gás e outros diretos',c.directCost,'#efc59f']];return `<div class="cost-bar" aria-label="Composição do custo do lote">${rows.map(([n,v,color])=>`<span style="width:${c.totalCost?v/c.totalCost*100:0}%;background:${color}" title="${n}: ${money(v)}"></span>`).join('')}</div><div class="summary-list">${rows.map(([n,v,color])=>`<div class="summary-row"><span><i class="legend-dot" style="background:${color}"></i>${n}</span><strong>${money(v)}</strong></div>`).join('')}<div class="summary-row total"><span>Custo do lote</span><strong>${money(c.totalCost)}</strong></div></div>`;}
function getRecipe(){return recipeBy(current.id)||activeRecipes()[0];}
function pricePage(){const r=getRecipe();if(!r)return empty('Primeiro, uma receita','Monte sua ficha para calcular o preço.',button('Criar receita','new-recipe'));const x=safeCost(r);if(x.error)return `${heading(esc(r.name))}${notice(esc(x.error),'warning')}<a class="button primary" href="#/edit/${esc(r.id)}">Revisar ficha</a>`;const c=x.c;if(priceRecipeId!==r.id){selectedScenario=r.priceScenario||state.scenarios[0].id;priceRecipeId=r.id;}const scenario=state.scenarios.find(s=>s.id===selectedScenario)||state.scenarios[0];const margin=scenario.margin??r.margin??40;let p={price:null,fees:null,profit:null,margin:null,breakEven:null};try{p=priceFor(c.unitCost,margin,scenario.fee,state.settings.taxRate);}catch{} 
return `${heading(esc(r.name),`${esc(r.category||'Receita')} · ${dec(r.yield)} ${esc(r.yieldUnit)} por lote`,`<a href="#/edit/${esc(r.id)}" class="button secondary">${icon('edit',18)} Editar receita</a>${button(icon('copy',18),'duplicate-recipe','icon-button',`data-id="${esc(r.id)}" aria-label="Duplicar receita"`)}`)}<div class="grid two price-grid"><section><div class="panel"><div class="panel-body">${select('Canal de venda','price-channel',scenario.id,state.scenarios.map(s=>[s.id,s.name]))}<div class="price-hero"><span>Preço sugerido</span><strong class="price-amount" id="suggested-price">${money(p.price)}</strong><span>/ ${labelUnit(r.yieldUnit)}</span></div><div class="margin-control"><span>${icon('percent',22)} Margem sobre a venda</span><div>${button(icon('minus',17),'margin-down','icon-button','aria-label="Diminuir margem"')}<label class="sr-only" for="target-margin">Margem desejada em porcentagem</label><input id="target-margin" inputmode="decimal" value="${val(margin)}"><span>%</span>${button(icon('plus',17),'margin-up','icon-button','aria-label="Aumentar margem"')}</div></div><p class="field-error" id="price-error" role="alert"></p><div class="summary-list"><div class="summary-row"><span>Custo por ${labelUnit(r.yieldUnit)}</span><strong>${money(c.unitCost)}</strong></div><div class="summary-row"><span>Taxas + tributo sobre a venda</span><strong>${pct(scenario.fee+state.settings.taxRate)}</strong></div><div class="summary-row"><span>Valor das taxas por venda</span><strong id="price-fees">${money(p.fees)}</strong></div><div class="summary-row"><span>Preço do lote completo</span><strong id="price-batch">${money(p.price==null?null:p.price*r.yield)}</strong></div><div class="summary-row green-result"><span>${icon('check',17)} Sobra estimada / ${esc(r.yieldUnit)}</span><strong id="price-profit">${money(p.profit)}</strong></div></div><p class="field-help text-center">Após os custos e taxas informados. Margem efetiva: <strong id="price-margin">${pct(p.margin)}</strong>.</p>${button(icon('save',19)+' Salvar ficha de preço','save-sheet','primary full',`data-id="${esc(r.id)}"`)}<a href="#/simulator/${esc(r.id)}" class="button secondary full">${icon('calculator',19)} Simular outros preços</a></div></div>${notice('A margem é calculada sobre o preço de venda. As taxas são editáveis em Custos de produção.')}</section><section class="panel"><div class="panel-heading"><h2>Composição do custo</h2>${icon('receipt',22)}</div><div class="panel-body">${breakdown(c)}<div class="summary-row"><span>Rendimento vendável</span><strong>${dec(r.yield)} ${esc(r.yieldUnit)}</strong></div><div class="summary-row"><span>Trabalho ativo</span><strong>${dec(r.minutes)} min · ${money(c.laborHourly)}/h</strong></div><div class="summary-row"><span>Tempo produtivo</span><strong>${dec(r.productionMinutes)} min</strong></div><div class="summary-row total"><span>Preço mínimo sem margem</span><strong id="break-even">${money(p.breakEven)}</strong></div><p class="field-help">Cobre os custos cadastrados e as taxas deste cenário.</p>${r.weightGrams>0?`<div class="notice info"><span>Equivalência do custo: <strong>${money(c.totalCost/(r.weightGrams/1000))}/kg</strong>, com as embalagens desta receita.</span></div>`:''}<details class="calculation-details"><summary>Ver quantidades e memória do cálculo</summary><div class="summary-list">${c.ingredientLines.map(l=>`<div class="summary-row"><span>${esc(l.name)}<small class="row-sub">${dec(l.quantity,3)} ${esc(l.unit)}</small></span><strong>${money(l.cost)}</strong></div>`).join('')}${c.packagingLines.map(l=>`<div class="summary-row"><span>${esc(l.name)} · ${dec(l.quantity)} ${esc(l.unit)}</span><strong>${money(l.cost)}</strong></div>`).join('')}</div><p class="field-help">Preço = custo unitário ÷ (1 − margem − taxas). O arredondamento para cima acontece somente no preço final.</p></details></div></section></div>`;}
function refreshPrice(){
  const r=getRecipe();const scenario=state.scenarios.find(s=>s.id===selectedScenario)||state.scenarios[0];const save=$('[data-action="save-sheet"]');
  try{const c=cost(r);const margin=num($('#target-margin').value);const p=priceFor(c.unitCost,margin,scenario.fee,state.settings.taxRate);$('#price-error').textContent='';$('#suggested-price').textContent=money(p.price);$('#price-fees').textContent=money(p.fees);$('#price-batch').textContent=money(p.price*r.yield);$('#price-profit').textContent=money(p.profit);$('#price-margin').textContent=pct(p.margin);$('#break-even').textContent=money(p.breakEven);if(save)save.disabled=false;return {r,c,p,scenario,margin};}
  catch(error){$('#price-error').textContent=error.message+' Ajuste a margem ou escolha outra forma de venda.';for(const key of ['suggested-price','price-fees','price-batch','price-profit','price-margin','break-even'])$('#'+key).textContent='—';if(save)save.disabled=true;return null;}
}
function costsPage(){const s=state.settings;return `${heading('Custos de produção','Seu tempo e a sua estrutura também fazem parte do preço.')}<form id="costs-form" novalidate><div class="grid two"><section><div class="panel"><div class="panel-heading"><h2>${icon('clock',22)} Sua hora de trabalho</h2></div><div class="panel-body"><div class="form-grid">${field('Remuneração mensal de referência (R$)','monthlyPay',s.monthlyPay,'inputmode="decimal" required')}${field('Horas de trabalho / mês','workHours',s.workHours,'inputmode="decimal" required')}</div><div class="summary-row total"><span>Sua hora de trabalho</span><strong id="labor-hour">${money(s.monthlyPay/s.workHours)} / hora</strong></div><p class="field-help">O valor remunera o trabalho ativo em cada lote. Não inclua o mesmo salário nos custos fixos.</p></div></div><div class="panel"><div class="panel-heading"><h2>${icon('costs',22)} Custos fixos</h2>${button(icon('plus',18)+' Despesa','add-fixed-cost','secondary small')}</div><div class="panel-body"><div id="fixed-rows">${s.fixedCosts.map(f=>fixedRow(f)).join('')}</div>${field('Horas produtivas planejadas / mês','productiveHours',s.productiveHours,'inputmode="decimal" required')}<div class="summary-row"><span>Total mensal incluído</span><strong id="fixed-month">${money(s.fixedCosts.reduce((a,f)=>a+f.value,0))}</strong></div><div class="summary-row total"><span>Rateio por hora produtiva</span><strong id="fixed-hour">${money(s.fixedCosts.reduce((a,f)=>a+f.value,0)/s.productiveHours)} / hora</strong></div><p class="field-help">O rateio depende das horas informadas. Se produzir menos horas no mês, a recuperação desses custos poderá ser menor.</p></div></div><div class="panel"><div class="panel-heading"><h2>${icon('package',22)} Custos diretos</h2></div><div class="panel-body">${field('Gás e energia padrão / novo lote (R$)','defaultDirectCost',s.defaultDirectCost??2,'inputmode="decimal"')}<p class="field-help">Sugestão inicial para novas receitas; cada lote pode ter um valor diferente. Exclua do rateio fixo as despesas cobradas diretamente.</p></div></div></section><section><div class="panel"><div class="panel-heading"><h2>${icon('card',22)} Formas de venda</h2></div><div class="panel-body">${state.scenarios.map(sc=>`<div class="scenario-setting"><strong>${icon(sc.icon,19)} ${esc(sc.name)}</strong><div class="form-grid">${field('Taxa sobre a venda (%)','fee-'+sc.id,sc.fee,'inputmode="decimal"')}${field('Margem própria (%) · opcional','margin-'+sc.id,sc.margin??'','inputmode="decimal" placeholder="Usar margem da receita"')}</div></div>`).join('')}${state.example?notice('As taxas de 4% e 23% são exemplos fictícios. Cadastre as condições do seu contrato.'):''}</div></div><div class="panel"><div class="panel-heading"><h2>${icon('percent',22)} Outros percentuais</h2></div><div class="panel-body">${field('Tributo sobre a venda (%) · opcional','taxRate',s.taxRate,'inputmode="decimal"')}<p class="field-help">Use somente um percentual que se aplique ao seu negócio. O app não determina alíquotas ou regime tributário.</p></div></div><p id="costs-error" class="field-error" role="alert"></p><button class="button primary full" type="submit">${icon('save',20)} Salvar custos</button></section></div></form>`;}
function fixedRow(f={name:'',value:0}){return `<div class="cost-item"><div class="field"><label class="sr-only">Nome da despesa</label><input class="fixed-name" aria-label="Nome da despesa fixa" value="${esc(f.name)}" placeholder="Ex.: parcela do aluguel" maxlength="100"></div><div class="field"><label class="sr-only">Valor mensal</label><input class="fixed-value" aria-label="Valor mensal da despesa" value="${val(f.value)}" inputmode="decimal"></div>${button(icon('close',17),'remove-fixed-cost','icon-button','aria-label="Remover despesa"')}</div>`;}
function costSettingsFromForm(){return {monthlyPay:num($('#monthlyPay').value),workHours:num($('#workHours').value),productiveHours:num($('#productiveHours').value),fixedCosts:$$('#fixed-rows .cost-item').map(row=>({name:$('.fixed-name',row).value.trim(),value:num($('.fixed-value',row).value)})),taxRate:num($('#taxRate').value),defaultDirectCost:num($('#defaultDirectCost').value)};}
function refreshCosts(){const s=costSettingsFromForm();const total=s.fixedCosts.reduce((a,f)=>a+f.value,0);$('#labor-hour').textContent=s.workHours>0?money(s.monthlyPay/s.workHours)+' / hora':'Informe as horas';$('#fixed-month').textContent=Number.isFinite(total)?money(total):'—';$('#fixed-hour').textContent=s.productiveHours>0&&Number.isFinite(total)?money(total/s.productiveHours)+' / hora':'Informe as horas';}
function initSim(r){sim={rid:r.id,margin:r.margin??40,sellPrice:r.price||0,discount:0,yield:r.yield,ingredientId:'',ingredientPrice:0,scenario:r.priceScenario||'pix'};}
function simulatorPage(){const r=getRecipe();if(!r)return empty('Vamos montar sua receita','O simulador precisa de uma ficha técnica.',button('Criar receita','new-recipe'));if(!sim||sim.rid!==r.id)initSim(r);const x=safeCost(r);if(x.error)return notice(esc(x.error),'warning');return `${heading('Simulador de preço','Experimente antes de mudar seus valores.')}<div class="grid two"><section><div class="panel"><div class="panel-body">${select('Receita','sim-recipe',r.id,activeRecipes().map(r=>[r.id,r.name]))}<div class="list-row compact">${thumb(r)}<div class="row-main"><strong>${esc(r.name)}</strong><span class="row-sub">Custo atual: ${money(x.c.unitCost)} / ${esc(r.yieldUnit)}</span></div></div><div class="form-grid">${field('Margem desejada (%)','sim-margin',sim.margin,'inputmode="decimal"')}${field('Rendimento simulado ('+esc(r.yieldUnit)+')','sim-yield',sim.yield,'inputmode="decimal"')}</div><details class="calculation-details"><summary>Simular alteração de um insumo</summary>${select('Insumo','sim-ingredient',sim.ingredientId,[['','Sem alteração'],...state.ingredients.filter(i=>!i.archived).map(i=>[i.id,i.name])])}${field('Novo preço da embalagem (R$)','sim-ingredient-price',sim.ingredientPrice||'','inputmode="decimal" placeholder="Preço total da embalagem"')}<p class="field-help">Esta simulação não altera o cadastro de insumos.</p></details><p id="sim-error" class="field-error" role="alert"></p></div></div><div class="panel"><div class="panel-heading"><h2>Quero cobrar</h2>${icon('percent',22)}</div><div class="panel-body"><div class="form-grid">${field('Preço de venda por '+esc(r.yieldUnit)+' (R$)','sim-sellPrice',sim.sellPrice,'inputmode="decimal"')}${field('Desconto sobre esse preço (%)','sim-discount',sim.discount,'inputmode="decimal"')}</div>${select('Forma de venda para este preço','sim-scenario',sim.scenario,state.scenarios.map(sc=>[sc.id,sc.name]))}<div class="price-hero small-price"><span>Margem que permanece</span><strong class="price-amount" id="sim-actual-margin">—</strong><span id="sim-actual-profit"></span></div><div id="sim-coverage"></div></div></div></section><section><div class="panel"><div class="panel-heading"><h2>Preços sugeridos</h2>${icon('calculator',22)}</div><div class="panel-body"><div class="summary-row total"><span>Custo simulado / ${esc(r.yieldUnit)}</span><strong id="sim-unit-cost">—</strong></div><div id="sim-scenarios"></div><p class="field-help">Taxas e margens por canal podem ser editadas em <a href="#/costs">Custos de produção</a>.</p>${button(icon('save',19)+' Salvar simulação','save-simulation','primary full')}</div></div>${notice('As simulações ficam separadas dos cadastros. Ao salvar, uma ficha registra os valores usados naquele momento.')}</section></div>`;}
function pullSim(){sim.margin=num($('#sim-margin').value);sim.yield=num($('#sim-yield').value);sim.sellPrice=num($('#sim-sellPrice').value);sim.discount=num($('#sim-discount').value);sim.ingredientId=$('#sim-ingredient').value;sim.ingredientPrice=num($('#sim-ingredient-price').value);sim.scenario=$('#sim-scenario').value;}
function simulated(){const r=structuredClone(recipeBy(sim.rid));r.yield=sim.yield;const ingredients=structuredClone(state.ingredients);if(sim.ingredientId){const i=ingredients.find(i=>i.id===sim.ingredientId);i.price=sim.ingredientPrice;}if(!Number.isFinite(sim.discount)||sim.discount<0||sim.discount>=100)throw Error('O desconto deve estar entre 0% e menos de 100%.');const c=calculateRecipe(r,ingredients,state.recipes.map(x=>x.id===r.id?r:x),state.settings);const scenario=state.scenarios.find(s=>s.id===sim.scenario);priceFor(1,sim.margin,0,0);const finalPrice=roundCurrency(sim.sellPrice*(1-sim.discount/100));const p=analyzePrice(c.unitCost,finalPrice,scenario.fee,state.settings.taxRate);return {r,c,p,scenario,ingredients};}
function refreshSim(){
  try{const {r,c,p}=simulated();$('#sim-error').textContent='';$('#sim-unit-cost').textContent=money(c.unitCost);$('#sim-scenarios').innerHTML=state.scenarios.map(sc=>{
    try{const result=priceFor(c.unitCost,sc.margin??sim.margin,sc.fee,state.settings.taxRate);return '<div class="scenario-card">'+icon(sc.icon,26)+'<div class="row-main"><strong>'+esc(sc.name)+' · taxa '+pct(sc.fee)+'</strong><span class="row-sub">Margem '+pct(sc.margin??sim.margin)+' · taxas '+money(result.fees)+'</span></div><strong class="scenario-price">'+money(result.price)+'</strong></div>';}
    catch(error){return '<div class="scenario-card"><div class="row-main"><strong>'+esc(sc.name)+'</strong><span class="field-error">'+esc(error.message)+'</span></div><span class="badge warning">Ajustar margem</span></div>';}
  }).join('');$('#sim-actual-margin').textContent=pct(p.margin);$('#sim-actual-margin').classList.toggle('negative',p.profit<0);$('#sim-actual-profit').textContent=money(p.profit)+' de sobra estimada / '+r.yieldUnit;$('#sim-coverage').innerHTML=notice(p.profit<0?'Este preço fica abaixo dos custos e taxas informados.':'Preço final com desconto: '+money(p.price)+'. Cobre os custos informados.',p.profit<0?'warning':'info');return true;}
  catch(error){$('#sim-error').textContent=error.message;$('#sim-unit-cost').textContent='—';$('#sim-scenarios').innerHTML='';$('#sim-actual-margin').textContent='—';$('#sim-actual-profit').textContent='';$('#sim-coverage').innerHTML='';return false;}
}
function sheetIsOld(sheet){try{return Math.abs(cost(recipeBy(sheet.recipeId)).unitCost-sheet.costs.unitCost)>0.00001;}catch{return true;}}
function sheetsPage(){const list=[...state.sheets].reverse();return `${heading('Minhas fichas','Cada preço salvo guarda os custos e taxas usados no cálculo.')}<div class="sheet-list grid two">${list.length?list.map(s=>`<section class="panel sheet-card"><div class="panel-body"><div class="list-row compact">${thumb(s.recipe)}<div class="row-main"><h2>${esc(s.name)}</h2><span class="row-sub">${dec(s.recipe.yield)} ${esc(s.recipe.yieldUnit)} · ${esc(s.scenario.name)}</span><span class="row-sub">Salva em ${date(s.createdAt)}${s.simulation?' · Simulação':''}</span></div></div><div class="summary-row"><strong class="scenario-price">${money(s.result.price)} / ${esc(s.recipe.yieldUnit)}</strong><span class="badge">Margem ${pct(s.result.margin)}</span></div>${sheetIsOld(s)?'<p class="field-help">Os custos atuais mudaram. Esta ficha preserva os valores originais.</p>':''}<div class="row-actions">${button('Abrir ficha','view-sheet','secondary',`data-id="${esc(s.id)}"`)}${button(icon('printer',19),'print-sheet','icon-button',`data-id="${esc(s.id)}" aria-label="Imprimir ${esc(s.name)}"`)}${button(icon('trash',18),'delete-sheet','icon-button',`data-id="${esc(s.id)}" aria-label="Excluir ficha de ${esc(s.name)}"`)}</div></div></section>`).join(''):empty('Seus preços, guardados com cuidado','Abra uma receita, confira o preço sugerido e toque em Salvar ficha.',`<a class="button primary" href="#/recipes">${icon('book',19)} Ver receitas</a>`)}</div>`;}
function morePage(){return `${heading('Seu caderno, do seu jeito','Preferências e cuidado com os dados da Kalyne.')}<section class="panel"><div class="list">${[['costs','Custos de produção','Sua hora, despesas e taxas','costs'],['simulator','Simulador','Compare preços e margens','calculator'],['sheets','Minhas fichas','Preços salvos, impressão e PDF','receipt']].map(([p,t,sub,ic])=>`<a class="list-row" href="#/${p}">${icon(ic,24)}<div class="row-main"><strong>${t}</strong><span class="row-sub">${sub}</span></div>${icon('chevron',19)}</a>`).join('')}</div></section><div class="grid two"><section class="panel"><div class="panel-heading"><h2>${icon('save',21)} Seus dados</h2></div><div class="panel-body"><p>Os cadastros ficam salvos neste navegador. Faça uma cópia para guardar ou levar os dados para outro aparelho.</p><div class="page-actions">${button(icon('download',19)+' Exportar backup','backup','primary')}${button(icon('upload',19)+' Restaurar backup','import-backup','secondary')}</div><input type="file" id="backup-file" accept="application/json,.json" hidden><p class="field-help">A restauração substitui o caderno deste navegador após sua confirmação.</p></div></section><section class="panel"><div class="panel-heading"><h2>${icon('book',21)} Começar com seus dados</h2></div><div class="panel-body"><p>As receitas e os insumos iniciais são exemplos. Você pode editá-los ou abrir um caderno vazio para cadastrar tudo do seu jeito.</p>${button('Começar com o caderno vazio','clear-data','secondary')}<p class="field-help">Seu custo de trabalho e suas taxas serão mantidos. Exporte um backup antes de limpar.</p></div></section></div>${notice('Neste app, taxas e custos são informados por você. O resultado é uma estimativa com base nos valores cadastrados.')}`;}
function render(){const parts=location.hash.replace(/^#\/?/,'').split('/').map(part=>{try{return decodeURIComponent(part);}catch{return '';}});current={page:parts[0]||'home',id:parts[1]||null};let content;try{content=({home:homePage,ingredients:ingredientsPage,recipes:recipesPage,edit:recipeEditor,price:pricePage,costs:costsPage,simulator:simulatorPage,sheets:sheetsPage,more:morePage}[current.page]||homePage)();}catch(e){content=notice('Não foi possível abrir esta tela: '+esc(e.message),'warning')+'<a href="#/home" class="button secondary">Voltar ao início</a>';}shell(content);if(current.page==='edit'&&draft){updateDraftTotals();syncMassYield();}if(current.page==='costs')costsBaseline=formFingerprint($('#costs-form'));if(current.page==='price'&&$('#target-margin'))refreshPrice();if(current.page==='simulator'&&sim)refreshSim();document.title='Kalyne Chocolateria · '+({home:'Início',ingredients:'Insumos',recipes:'Receitas',edit:'Ficha técnica',price:'Preço sugerido',costs:'Custos',simulator:'Simulador',sheets:'Minhas fichas',more:'Preferências'}[current.page]||'Início');}
function openModal(title,body,footer=''){previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-header"><h2 id="dialog-title">${title}</h2>${button(icon('close',22),'close-modal','icon-button','aria-label="Fechar"')}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.classList.add('modal-open');$('#app').inert=true;($('.modal input')||$('.modal select')||$('.modal button'))?.focus();}
function closeModal(){$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');$('#app').inert=false;pendingLeave=null;previousFocus?.isConnected&&previousFocus.focus();}
function showIngredientModal(i){const item=i||{id:'',name:'',category:ingredientTab==='packaging'?'packaging':'ingredient',price:'',quantity:'',unit:'g',brand:''};openModal(i?'Editar insumo':'Novo insumo',`<form id="ingredient-form" data-id="${esc(item.id)}" novalidate>${field('Nome do ingrediente ou embalagem','ing-name',item.name,'required maxlength="100" placeholder="Ex.: Chocolate meio amargo"')}${select('Tipo de insumo','ing-category',item.category,[['ingredient','Ingrediente'],['packaging','Embalagem']])}<div class="form-grid">${field('Quanto você pagou? (R$)','ing-price',item.price,'inputmode="decimal" required placeholder="30,00"')}${field('Quanto veio na embalagem?','ing-quantity',item.quantity,'inputmode="decimal" required placeholder="1"')}</div>${select('Unidade da embalagem comprada','ing-unit',item.unit,[['g','Gramas (g)'],['kg','Quilogramas (kg)'],['ml','Mililitros (ml)'],['L','Litros (L)'],['un','Unidades (un)']])}${field('Marca ou fornecedor · opcional','ing-brand',item.brand,'maxlength="100"')}<div class="notice info"><span id="ingredient-preview">Ex.: 1 kg por R$ 30 custa R$ 0,03 por grama. Use vírgula para decimais.</span></div><p id="ingredient-error" class="field-error" role="alert"></p></form>`,`${i?button(icon('trash',17)+' Arquivar','archive-ingredient','ghost danger',`data-id="${esc(i.id)}"`):''}${button('Cancelar','close-modal','secondary')}<button type="submit" form="ingredient-form" class="button primary">${icon('save',18)} Salvar insumo</button>`);}
function confirmAction(title,text,action,extra=''){openModal(title,`<p>${text}</p>`,button('Cancelar','close-modal','secondary')+button('Confirmar',action,'primary',extra));}
function saveSnapshot({r,c,p,scenario,margin,ingredients=state.ingredients,simulation=false}){const sheet={id:id(),recipeId:r.id,name:r.name,createdAt:stamp(),recipe:structuredClone(r),ingredients:structuredClone(ingredients),recipes:structuredClone(state.recipes.map(item=>item.id===r.id?r:item)),settings:structuredClone(state.settings),scenario:{...structuredClone(scenario),margin},costs:structuredClone(c),result:structuredClone(p),simulation};updateState(next=>{next.sheets.push(sheet);const recipe=next.recipes.find(x=>x.id===r.id);if(recipe&&!simulation){if(scenario.margin==null)recipe.margin=margin;recipe.price=p.price;recipe.priceScenario=scenario.id;}});draft=null;draftBaseline=null;notify(simulation?'Simulação salva em Minhas fichas.':'Ficha salva com os valores deste cálculo.');return sheet;}
function sheetDetail(s){return `<div class="sheet-document"><div class="sheet-brand"><img src="./assets/logo.png" alt="Kalyne Chocolateria"></div><h2>${esc(s.name)}</h2><p>${esc(s.scenario.name)} · ${date(s.createdAt)}${s.simulation?' · Simulação':''}</p><div class="price-hero"><span>Preço salvo / ${esc(s.recipe.yieldUnit)}</span><strong class="price-amount">${money(s.result.price)}</strong><span>Margem efetiva ${pct(s.result.margin)}</span></div>${breakdown(s.costs)}<div class="summary-row"><span>Rendimento</span><strong>${dec(s.recipe.yield)} ${esc(s.recipe.yieldUnit)}</strong></div><div class="summary-row"><span>Custo unitário</span><strong>${money(s.costs.unitCost)}</strong></div><div class="summary-row"><span>Taxas por venda</span><strong>${money(s.result.fees)}</strong></div><div class="summary-row total"><span>Sobra estimada por venda</span><strong>${money(s.result.profit)}</strong></div><h3>Ingredientes e embalagens</h3>${[...s.costs.ingredientLines,...s.costs.packagingLines].map(l=>`<div class="summary-row"><span>${esc(l.name)} · ${dec(l.quantity,3)} ${esc(l.unit)}</span><strong>${money(l.cost)}</strong></div>`).join('')}<p class="field-help">Ficha preservada com os custos cadastrados na data do cálculo. A sobra é uma estimativa após os custos e taxas informados.</p></div>`;}
function printSheet(s){$('#print-root')?.remove();const print=document.createElement('div');print.id='print-root';print.className='print-sheet';print.innerHTML=sheetDetail(s);document.body.append(print);window.print();}
function exportBackup(){const blob=new Blob([recoveryRaw??JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=(recoveryRaw?'kalyne-recuperacao-':'kalyne-backup-')+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);notify('Backup exportado. Guarde o arquivo em um lugar seguro.');}
async function importBackup(file){try{if(!file)return;if(file.size>5_000_000)throw Error('Use um arquivo de backup com até 5 MB.');const data=validateState(JSON.parse(await file.text()));openModal('Restaurar este backup?',`<p>O caderno deste navegador será substituído por <strong>${data.ingredients.length} insumos, ${data.recipes.length} receitas e ${data.sheets.length} fichas</strong>.</p><p>Exporte seus dados atuais se quiser manter uma cópia.</p>`,button('Cancelar','close-modal','secondary')+button('Restaurar backup','confirm-import','primary'));pendingImport=data;}catch(e){notify('Não foi possível restaurar: '+e.message);}}
let pendingImport=null;

document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;try{switch(action){
 case 'new-recipe':makeDraft();draft.directCost=state.settings.defaultDirectCost??2;draftBaseline=JSON.stringify(draft);route('edit');break;
 case 'new-ingredient':showIngredientModal();break;
 case 'edit-ingredient':showIngredientModal(state.ingredients.find(i=>i.id===b.dataset.id));break;
 case 'close-modal':closeModal();break;
 case 'confirm-leave':{const leave=pendingLeave;closeModal();draft=null;draftBaseline=null;costsBaseline=null;if(remoteChanged){try{state=validateState(JSON.parse(localStorage.getItem(STORAGE)));remoteChanged=false;loadWarning='';sim=null;}catch{persistenceBlocked=true;}}leave?.();break;}
 case 'ingredient-tab':ingredientTab=b.dataset.value;render();break;
 case 'archive-ingredient':updateState(next=>next.ingredients.find(i=>i.id===b.dataset.id).archived=true);closeModal();render();notify('Insumo arquivado. As receitas existentes mantêm a referência.');break;
 case 'restore-ingredient':updateState(next=>next.ingredients.find(i=>i.id===b.dataset.id).archived=false);render();notify('Insumo restaurado.');break;
 case 'add-recipe-line':case 'add-packaging-line':{pullDraft();const key=action==='add-recipe-line'?'items':'packaging';const options=key==='items'?optionsForItem():state.ingredients.filter(i=>!i.archived&&i.category==='packaging').map(i=>[i.id,i.name]);if(!options.length){notify('Cadastre primeiro um '+(key==='items'?'ingrediente':'tipo de embalagem')+' em Insumos.');break;}const choice=options[0][0];const [type,rid]=key==='items'?choice.split(':'):['ingredient',choice];const target=type==='recipe'?recipeBy(rid):state.ingredients.find(i=>i.id===rid);draft[key].push({type,id:rid,quantity:1,unit:type==='recipe'?target.yieldUnit:baseUnit(target.unit)});render();break;}
 case 'remove-line':pullDraft();draft[b.dataset.key].splice(Number(b.dataset.index),1);render();break;
 case 'scale-recipe':pullDraft();openModal('Ajustar o tamanho do lote',`<form id="scale-form">${field('Multiplicar as quantidades por','scale-factor',2,'inputmode="decimal" required')}<p class="field-help">Ingredientes, embalagens, rendimento, peso e custos diretos serão multiplicados. Confira os tempos de produção e trabalho depois do ajuste.</p></form>`,button('Cancelar','close-modal','secondary')+'<button class="button primary" type="submit" form="scale-form">Ajustar lote</button>');break;
 case 'duplicate-recipe':{const original=recipeBy(b.dataset.id);draft=structuredClone(original);draft.id=id();draft.name+=' · cópia';draft.archived=false;draftBaseline=JSON.stringify(draft);current.id=null;route('edit');notify('Cópia pronta para editar. Salve para adicionar ao caderno.');break;}
 case 'margin-up':case 'margin-down':$('#target-margin').value=val(Math.max(0,num($('#target-margin').value)+(action==='margin-up'?1:-1)));refreshPrice();break;
 case 'save-sheet':{const x=refreshPrice();if(x){saveSnapshot(x);route('sheets');}break;}
 case 'add-fixed-cost':$('#fixed-rows').insertAdjacentHTML('beforeend',fixedRow());break;
 case 'remove-fixed-cost':b.closest('.cost-item').remove();refreshCosts();break;
 case 'save-simulation':pullSim();if(refreshSim()){const x=simulated();saveSnapshot({...x,margin:sim.margin,simulation:true});route('sheets');}break;
 case 'view-sheet':{const s=state.sheets.find(s=>s.id===b.dataset.id);openModal('Ficha de preço',sheetDetail(s),button(icon('printer',18)+' Imprimir / salvar PDF','print-sheet','primary',`data-id="${esc(s.id)}"`)+`<a href="#/price/${esc(s.recipeId)}" data-action="recalculate-sheet" class="button secondary">Recalcular com custos atuais</a>`);break;}
 case 'recalculate-sheet':closeModal();break;
 case 'print-sheet':{const s=state.sheets.find(s=>s.id===b.dataset.id);printSheet(s);break;}
 case 'delete-sheet':confirmAction('Excluir esta ficha?','A receita e os insumos continuarão no seu caderno.','confirm-delete-sheet',`data-id="${esc(b.dataset.id)}"`);break;
 case 'confirm-delete-sheet':updateState(next=>next.sheets=next.sheets.filter(s=>s.id!==b.dataset.id));closeModal();render();notify('Ficha excluída.');break;
 case 'backup':exportBackup();break;
 case 'import-backup':$('#backup-file').click();break;
 case 'confirm-import':if(pendingImport){const restored=pendingImport;updateState(next=>{for(const k of Object.keys(next))delete next[k];Object.assign(next,restored);},{replace:true});pendingImport=null;draft=null;sim=null;closeModal();route('home');render();notify('Backup restaurado.');}break;
 case 'clear-data':confirmAction('Abrir um caderno vazio?','Isso remove todos os insumos, receitas e fichas deste navegador. Seus custos e taxas serão mantidos. Exporte um backup para guardar uma cópia.','confirm-clear');break;
 case 'confirm-clear':updateState(next=>{next.ingredients=[];next.recipes=[];next.sheets=[];next.example=false;},{replace:true});draft=null;sim=null;closeModal();route('home');render();notify('Caderno pronto para receber os seus dados.');break;
}}catch(e){notify(e.message);}});

document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;try{
 if(form.id==='ingredient-form'){const item={id:form.dataset.id||id(),name:$('#ing-name').value.trim(),category:$('#ing-category').value,price:num($('#ing-price').value),quantity:num($('#ing-quantity').value),unit:$('#ing-unit').value,brand:$('#ing-brand').value.trim(),updatedAt:new Date().toISOString().slice(0,10)};if(!item.name)throw Error('Informe o nome do insumo.');if(!$('#ing-price').value.trim()||!$('#ing-quantity').value.trim())throw Error('Informe o preço pago e a quantidade da embalagem.');unitCost(item);updateState(next=>{const index=next.ingredients.findIndex(i=>i.id===item.id);if(index<0)next.ingredients.push(item);else next.ingredients[index]={...next.ingredients[index],...item};});ingredientTab=item.category;closeModal();render();notify('Insumo salvo. Os cálculos atuais usam o novo valor.');}
 if(form.id==='recipe-form'){pullDraft();if(!draft.name)throw Error('Dê um nome para a receita.');if(!draft.items.length)throw Error('Adicione pelo menos um ingrediente.');const recipes=state.recipes.filter(r=>r.id!==draft.id).concat([draft]);calculateRecipe(draft,state.ingredients,recipes,state.settings);const saved=structuredClone(draft);updateState(next=>{const index=next.recipes.findIndex(r=>r.id===saved.id);if(index<0)next.recipes.push(saved);else next.recipes[index]=saved;});draft=null;draftBaseline=null;selectedScenario='pix';priceRecipeId=null;route('price',saved.id);notify('Receita salva. Confira seu preço sugerido.');}
 if(form.id==='scale-form'){const factor=num($('#scale-factor').value);if(!Number.isFinite(factor)||factor<=0)throw Error('Informe um fator maior que zero.');draft.items.forEach(i=>i.quantity*=factor);draft.packaging.forEach(i=>i.quantity*=factor);draft.yield*=factor;if(draft.weightGrams>0)draft.weightGrams*=factor;draft.directCost*=factor;closeModal();render();notify('Quantidades ajustadas. Confira rendimento e tempos antes de salvar.');}
 if(form.id==='costs-form'){const settings=costSettingsFromForm();if(settings.defaultDirectCost<0||!Number.isFinite(settings.defaultDirectCost))throw Error('O custo direto deve ser zero ou maior.');if(settings.fixedCosts.some(f=>!f.name.trim()))throw Error('Dê um nome para cada despesa fixa.');const scenarios=state.scenarios.map(sc=>({...sc,fee:num($('#fee-'+sc.id).value),margin:$('#margin-'+sc.id).value.trim()===''?null:num($('#margin-'+sc.id).value)}));calculateRecipe({id:'validation',name:'Validação',yield:1,yieldUnit:'un',minutes:0,productionMinutes:0,directCost:0,items:[],packaging:[]},[],[],settings);for(const sc of scenarios)priceFor(1,sc.margin??0,sc.fee,settings.taxRate);updateState(next=>{next.settings=settings;next.scenarios=scenarios;});notify('Custos salvos. Os cálculos atuais foram atualizados.');render();}
 }catch(e){const target=({'ingredient-form':'ingredient-error','recipe-form':'draft-error','costs-form':'costs-error'}[form.id]);if(target&&$('#'+target)){$('#'+target).textContent=e.message;$('#'+target).scrollIntoView({block:'nearest',behavior:'smooth'});}else notify(e.message);}});
document.addEventListener('input',event=>{const el=event.target;try{
 if(el.id==='ingredient-search'){ingredientSearch=el.value;$('#ingredient-results').innerHTML=ingredientResults();}
 if(el.id==='recipe-search'){recipeSearch=el.value;$('#recipe-results').innerHTML=recipeResults();}
 if(el.closest('#recipe-form')){pullDraft();updateDraftTotals();}
 if(el.id==='target-margin')refreshPrice();
 if(el.closest('#costs-form'))refreshCosts();
 if(el.id.startsWith('sim-')&&el.id!=='sim-recipe'){pullSim();refreshSim();}
 if(el.closest('#ingredient-form')){try{const p=num($('#ing-price').value),q=num($('#ing-quantity').value),u=$('#ing-unit').value;if(q>0&&Number.isFinite(p)){const each=unitCost({price:p,quantity:q,unit:u});$('#ingredient-preview').textContent=money(p)+' por '+dec(q,3)+' '+u+' = '+dec(each,5)+' real por '+baseUnit(u)+'.';}}catch{}}
 }catch{} });
document.addEventListener('change',event=>{const el=event.target;if(el.id==='price-channel'){selectedScenario=el.value;render();}if(el.id==='sim-recipe'){sim=null;route('simulator',el.value);}if(el.id==='sim-ingredient'){const target=state.ingredients.find(i=>i.id===el.value);if(target){$('#sim-ingredient-price').value=val(target.price);pullSim();refreshSim();}}if(el.id==='backup-file')importBackup(el.files[0]);if(el.matches('[data-line-field="id"]')){const row=el.closest('.recipe-line');const line=draft[row.dataset.key][Number(row.dataset.index)];const target=line.type==='recipe'?recipeBy(line.id):state.ingredients.find(i=>i.id===line.id);line.unit=line.type==='recipe'?target.yieldUnit:baseUnit(target.unit);render();}});
document.addEventListener('keydown',e=>{const modal=$('.modal');if(!modal)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const controls=$$('button,input,select,textarea,a[href]',modal).filter(el=>!el.disabled&&!el.hidden);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{
  if(hasUnsavedChanges()) { const target=location.hash;history.replaceState(null,'','#/'+current.page+(current.id?'/'+encodeURIComponent(current.id):''));confirmLeave(()=>{location.hash=target;});return; }
  if(current.page==='edit'){draft=null;draftBaseline=null;}render();window.scrollTo({top:0,behavior:'instant'});
});
window.addEventListener('afterprint',()=>$('#print-root')?.remove());
render();

function syncMassYield(){if(!draft||!$('#recipe-weight'))return;const mass=draft.yieldUnit!=='un';$('#recipe-weight').readOnly=mass;if(mass){draft.weightGrams=draft.yieldUnit==='kg'?draft.yield*1000:draft.yield;$('#recipe-weight').value=val(draft.weightGrams);}}
function formFingerprint(form){return form?JSON.stringify([...form.querySelectorAll('input,select,textarea')].map(el=>[el.id||el.className,el.value])):'';}
function hasUnsavedChanges(){if(current.page==='edit'&&draft&&$('#recipe-form')){pullDraft();return draftBaseline!==JSON.stringify(draft);}return current.page==='costs'&&costsBaseline!==null&&costsBaseline!==formFingerprint($('#costs-form'));}
function confirmLeave(leave){openModal('Você tem alterações não salvas','<p>Salve suas alterações antes de sair ou descarte apenas o que ainda não foi salvo.</p>',button('Continuar editando','close-modal','secondary')+button('Descartar alterações','confirm-leave','primary'));pendingLeave=leave;}
document.addEventListener('click',event=>{const link=event.target.closest('a[href^="#/"]');if(!link||link.hash===location.hash||!hasUnsavedChanges())return;event.preventDefault();event.stopImmediatePropagation();const target=link.hash;confirmLeave(()=>{location.hash=target;});},true);
window.addEventListener('beforeunload',event=>{if(hasUnsavedChanges()){event.preventDefault();event.returnValue='';}});
window.addEventListener('storage',event=>{
  if(event.key!==STORAGE)return;
  if(hasUnsavedChanges()){remoteChanged=true;loadWarning='Outra aba alterou os dados. Suas alterações nesta tela foram preservadas. Reabra os dados atuais antes de salvar.';notify(loadWarning);return;}
  try{state=validateState(event.newValue?JSON.parse(event.newValue):seedState());remoteChanged=false;draft=null;draftBaseline=null;sim=null;render();notify('Caderno atualizado com as alterações da outra aba.');}
  catch{persistenceBlocked=true;loadWarning='Os dados alterados em outra aba precisam de recuperação. Seus dados desta sessão foram preservados.';render();}
});
